import 'package:audioplayers/audioplayers.dart';
import 'package:flutter/foundation.dart';

/// The mala-completion bell.
///
/// The WAV is generated by `tool/make_bell.py` and bundled as an asset, so
/// there is no recorded audio in the repo. Playback is best-effort: a phone
/// with no audio, or a web browser that blocks autoplay, must never break the
/// counter — so every failure is swallowed.
class Bell {
  Bell._();

  static final AudioPlayer _player = AudioPlayer(playerId: 'mission-bell');
  static bool _initialised = false;
  static bool _failed = false;

  static const String asset = 'assets/sounds/bell.wav';

  /// Play the bell. Safe to call from anywhere; never throws.
  static Future<void> ring() async {
    if (_failed) return;
    if (kIsWeb) {
      // Browsers require a user gesture before audio, and the first tap is
      // one — so this is fine, but a failure here must not be fatal.
    }
    try {
      if (!_initialised) {
        await _player.setReleaseMode(ReleaseMode.stop);
        await _player.setSource(AssetSource(asset));
        _initialised = true;
      }
      await _player.stop();
      await _player.resume();
    } catch (e) {
      // Audio is a nicety, not a feature gate — stop trying after a failure.
      _failed = true;
      if (kDebugMode) {
        debugPrint('[bell] unavailable: $e');
      }
    }
  }

  static Future<void> dispose() async {
    try {
      await _player.dispose();
    } catch (_) {}
  }
}
